    use diesel::prelude::*;

    let mut conn = pool.get().expect("Failed to get connection");

    diesel::sql_query("TRUNCATE TABLE file_links CASCADE")
        .execute(&mut conn)
        .ok();
    diesel::sql_query("TRUNCATE TABLE files CASCADE")
        .execute(&mut conn)
        .ok();
