use bytes::Bytes;
use reqwest::Client;
use thiserror::Error;

#[derive(Error, Debug)]
pub enum StorageError {
    #[error("HTTP request failed: {0}")]
    RequestFailed(#[from] reqwest::Error),
    #[error("Storage operation failed: {0}")]
    OperationFailed(String),
}

#[derive(Clone)]
pub struct ObjectStorageClient {
    client: Client,
    base_url: String,
    bucket: String,
}

impl ObjectStorageClient {
    pub fn new(base_url: String, bucket: String) -> Self {
        Self {
            client: Client::new(),
            base_url,
            bucket,
        }
    }

    pub async fn upload(
        &self,
        key: &str,
        data: Bytes,
        content_type: Option<&str>,
    ) -> Result<(), StorageError> {
        let url = format!("{}/buckets/{}/objects/{}", self.base_url, self.bucket, key);

        let mut req = self.client.put(&url).body(data);

        if let Some(ct) = content_type {
            req = req.header("Content-Type", ct);
        }

        let response = req.send().await?;

        if !response.status().is_success() {
            return Err(StorageError::OperationFailed(format!(
                "Upload failed with status: {}",
                response.status()
            )));
        }

        Ok(())
    }

    pub async fn download(&self, key: &str) -> Result<Bytes, StorageError> {
        let url = format!("{}/buckets/{}/objects/{}", self.base_url, self.bucket, key);

        let response = self.client.get(&url).send().await?;

        if !response.status().is_success() {
            return Err(StorageError::OperationFailed(format!(
                "Download failed with status: {}",
                response.status()
            )));
        }

        Ok(response.bytes().await?)
    }

    pub async fn delete(&self, key: &str) -> Result<(), StorageError> {
        let url = format!("{}/buckets/{}/objects/{}", self.base_url, self.bucket, key);

        let response = self.client.delete(&url).send().await?;

        if !response.status().is_success() && response.status().as_u16() != 404 {
            return Err(StorageError::OperationFailed(format!(
                "Delete failed with status: {}",
                response.status()
            )));
        }

        Ok(())
    }
}

