    let tenant: Tenant = tenants::table
        .find(updated_file.tenant_oid)
        .first(&mut conn)
        .map_err(|_| AppError::DatabaseError)?;

    let purpose: Purpose = purposes::table
        .find(updated_file.purpose_oid)
        .first(&mut conn)
        .map_err(|_| AppError::DatabaseError)?;

    Ok(Json(FileResponse {
