        .layer(cors.clone())
        .with_state(state.clone());

    let private_app = Router::new()
        .route("/files/:file_id", delete(handlers_private::delete_file))
        .route("/files/:file_id", put(handlers_private::update_file))
        .route("/files/:file_id", get(handlers_private::get_file_private))
        .route("/files", get(handlers_private::list_files))
        .route("/links", post(handlers_private::create_link))
        .route("/links/:link_id", get(handlers_private::get_link))
        .route("/links/:link_id", delete(handlers_private::delete_link))
        .layer(cors)
        .with_state(state);

    let public_addr = format!("{}:{}", config.public_host, config.public_port);
    let private_addr = format!("{}:{}", config.private_host, config.private_port);

    tracing::info!("Starting public API on {}", public_addr);
    tracing::info!("Starting private API on {}", private_addr);

    let public_listener = tokio::net::TcpListener::bind(&public_addr).await?;
    let private_listener = tokio::net::TcpListener::bind(&private_addr).await?;

    let public_serve = tokio::spawn(async move { axum::serve(public_listener, public_app).await });

    let private_serve =
        tokio::spawn(async move { axum::serve(private_listener, private_app).await });

    tokio::select! {
        result = public_serve => {
            result??;
        }
        result = private_serve => {
            result??;
        }
    }

    Ok(())
}

use std::sync::Mutex;
use std::time::{SystemTime, UNIX_EPOCH};

const EPOCH: u64 = 1640995200000;
const WORKER_ID_BITS: u64 = 5;
const DATACENTER_ID_BITS: u64 = 5;
const SEQUENCE_BITS: u64 = 12;

const MAX_WORKER_ID: u64 = (1 << WORKER_ID_BITS) - 1;
const MAX_DATACENTER_ID: u64 = (1 << DATACENTER_ID_BITS) - 1;
const MAX_SEQUENCE: u64 = (1 << SEQUENCE_BITS) - 1;

const WORKER_ID_SHIFT: u64 = SEQUENCE_BITS;
const DATACENTER_ID_SHIFT: u64 = SEQUENCE_BITS + WORKER_ID_BITS;
const TIMESTAMP_SHIFT: u64 = SEQUENCE_BITS + WORKER_ID_BITS + DATACENTER_ID_BITS;

pub struct SnowflakeGenerator {
    worker_id: u64,
    datacenter_id: u64,
    sequence: u64,
    last_timestamp: u64,
}

impl SnowflakeGenerator {
    pub fn new(worker_id: u64, datacenter_id: u64) -> Result<Self, String> {
        if worker_id > MAX_WORKER_ID {
            return Err(format!("Worker ID must be between 0 and {}", MAX_WORKER_ID));
        }
        if datacenter_id > MAX_DATACENTER_ID {
            return Err(format!(
                "Datacenter ID must be between 0 and {}",
                MAX_DATACENTER_ID
            ));
        }

        Ok(Self {
            worker_id,
            datacenter_id,
            sequence: 0,
            last_timestamp: 0,
        })
    }

    pub fn generate(&mut self) -> Result<i64, String> {
        let mut timestamp = self.current_timestamp()?;

        if timestamp < self.last_timestamp {
            return Err("Clock moved backwards".to_string());
        }

        if timestamp == self.last_timestamp {
            self.sequence = (self.sequence + 1) & MAX_SEQUENCE;
            if self.sequence == 0 {
                timestamp = self.wait_next_millis(self.last_timestamp)?;
            }
        } else {
            self.sequence = 0;
        }

        self.last_timestamp = timestamp;

        let id = ((timestamp - EPOCH) << TIMESTAMP_SHIFT)
            | (self.datacenter_id << DATACENTER_ID_SHIFT)
            | (self.worker_id << WORKER_ID_SHIFT)
            | self.sequence;

        Ok(id as i64)
    }

    fn current_timestamp(&self) -> Result<u64, String> {
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_millis() as u64)
            .map_err(|e| format!("Failed to get system time: {}", e))
    }

    fn wait_next_millis(&self, last_timestamp: u64) -> Result<u64, String> {
        let mut timestamp = self.current_timestamp()?;
        while timestamp <= last_timestamp {
            timestamp = self.current_timestamp()?;
        }
        Ok(timestamp)
    }
}

pub struct SnowflakeGeneratorWrapper(Mutex<SnowflakeGenerator>);

impl SnowflakeGeneratorWrapper {
    pub fn new(worker_id: u64, datacenter_id: u64) -> Result<Self, String> {
        Ok(Self(Mutex::new(SnowflakeGenerator::new(
            worker_id,
            datacenter_id,
        )?)))
    }

    pub fn generate(&self) -> Result<i64, String> {
        self.0
            .lock()
            .map_err(|e| format!("Lock poisoned: {}", e))?
            .generate()
    }
}

pub fn generate_prefixed_id(prefix: &str, oid: i64) -> String {
    use rand::Rng;
    let random_suffix: String = rand::thread_rng()
        .sample_iter(&rand::distributions::Alphanumeric)
        .take(20)
        .map(char::from)
        .collect();
    format!("{}_{:x}{}", prefix, oid, random_suffix)
}

#[cfg(test)]
mod tests {
    use super::*;
